const takeVersionNumber = `-- name: TakeVersionNumber :one
UPDATE modeldev_datasets
SET next_version_number = next_version_number + 1
WHERE tenant_id = $1::uuid
  AND dataset_id = $2::uuid
  AND state = 'ACTIVE'
RETURNING (next_version_number - 1)::bigint AS version_number
`

type TakeVersionNumberParams struct {
	TenantID  pgtype.UUID
	DatasetID pgtype.UUID
}

// The version sequence advances in the acceptance transaction; a failed or
// cancelled task leaves a permanent gap and never recycles the number.
func (q *Queries) TakeVersionNumber(ctx context.Context, arg TakeVersionNumberParams) (int64, error) {
	row := q.db.QueryRow(ctx, takeVersionNumber, arg.TenantID, arg.DatasetID)
	var version_number int64
	err := row.Scan(&version_number)
	return version_number, err
}

